import type { AbstractIntlMessages } from "next-intl";
import manifest from "./client-namespaces.json";

/**
 * The catalog subset shipped to client components.
 *
 * `client-namespaces.json` is generated by `scripts/i18n/client-namespaces.mjs`
 * from the client import graph of each route section. Server components read
 * messages on the server and need none of this; shipping the whole catalog put
 * 450–500 KB of JSON into every page's RSC payload.
 */

export type ClientSection = keyof typeof manifest.sections;

const FULL = "*";

/**
 * Messages for one provider: the shell alone (`section` omitted, for the
 * locale layout), or the shell plus one section's namespaces. A section the
 * scan could not resolve statically gets the whole catalog.
 */
export function pickClientMessages(
  messages: AbstractIntlMessages,
  section?: ClientSection,
): AbstractIntlMessages {
  const own: readonly string[] | typeof FULL =
    section === undefined ? [] : (manifest.sections[section] as readonly string[] | typeof FULL);
  if (own === FULL) return messages;

  const picked: AbstractIntlMessages = {};
  for (const name of [...manifest.shell, ...own]) {
    const value = messages[name];
    if (value !== undefined) picked[name] = value;
  }
  return picked;
}
